"""Saved schedules for page display: temporary SQLite, generated by real local agent."""
import pytest
from sqlalchemy import select
from app.models import StudyPlan
from tests.test_study_notification_flow import flow,create
from tests.test_enhanced_study_flow import enhanced,generate

@pytest.mark.parametrize('kind',['short','long','both'])
@pytest.mark.parametrize('review',[False,True])
async def test_detail_returns_exact_saved_review_and_schedule(enhanced,kind,review):
 result=(await generate(enhanced,plan_type=kind,ebbinghaus_enabled=review,daily_hours=1.5)).json()['result']
 url='/api/v1/study/plans/'+result['plan_id']
 for _ in range(2):
  response=await enhanced.client.get(url,headers=enhanced.alice);assert response.status_code==200
  detail=response.json()
  for field in ['short_term_plan','long_term_plan','ebbinghaus_nodes']:
   assert field in detail
   assert detail[field]==result[field]
 async with enhanced.factory() as db:
  plan=await db.get(StudyPlan,result['plan_id'])
  assert plan.ebbinghaus_nodes==detail['ebbinghaus_nodes']
 assert (await enhanced.client.get(url,headers=enhanced.bob)).status_code==404

async def test_legacy_manual_plan_has_no_invented_nodes(flow):
 id=await create(flow)
 response=await flow.client.get('/api/v1/study/plans/'+id,headers=flow.alice)
 assert response.status_code==200
 data=response.json();assert 'ebbinghaus_nodes' in data
 assert data['ebbinghaus_nodes']==[]
 assert data['short_term_plan'] is None and data['long_term_plan'] is None

async def test_modified_persisted_nodes_are_read_without_recomputation(enhanced):
 id=(await generate(enhanced)).json()['result']['plan_id']
 saved=[{'day':99,'review':True,'description':'历史自定义 <b>纯文字</b>'}]
 async with enhanced.factory() as db:
  plan=await db.get(StudyPlan,id);plan.ebbinghaus_nodes=saved;await db.commit()
 data=(await enhanced.client.get('/api/v1/study/plans/'+id,headers=enhanced.alice)).json()
 assert data.get('ebbinghaus_nodes')==saved
 assert (await enhanced.client.get('/api/v1/study/plans/'+id+'/ebbinghaus',headers=enhanced.alice)).json()['ebbinghaus_nodes']==saved
